def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value.strip()
        if "<" in value and ">" in value[value.find("<") + 1:]:
            value = value[value.find("<") + 1:value.find(">", value.find("<") + 1)]
        value = value.strip().lower()

        if value.count("@") == 1:
            local, domain = value.split("@")
            if domain in ("gmail.com", "googlemail.com"):
                local = local.split("+", 1)[0].replace(".", "")
                value = f"{local}@gmail.com"

        if value.count("@") != 1:
            return value, False
        local, domain = value.split("@")
        valid = bool(local) and "." in domain and not domain.startswith(".") and not domain.endswith(".")
        return value, valid

    def normalize_phone(value):
        value = re.split(r"ext|x|#", value, maxsplit=1, flags=re.IGNORECASE)[0]
        digits = "".join(ch for ch in value if "0" <= ch <= "9")
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        valid = len(digits) == 10 and digits[0] not in "01"
        return digits, valid

    def normalize_zip(value):
        value = value.strip()
        if re.fullmatch(r"\d{5}-\d{4}", value):
            value = value.split("-", 1)[0]
        if re.fullmatch(r"\d{4}", value):
            value = "0" + value
        return value if re.fullmatch(r"\d{5}", value) else ""

    def normalize_name(value):
        value = value.strip()
        if value.isupper() or value.islower():
            value = value.title()
        return value

    def parse_updated(value):
        for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError(f"Unsupported updated value: {value!r}")

    prepared = []
    for index, row in enumerate(rows):
        email, email_valid = normalize_email(row["email"])
        phone, phone_valid = normalize_phone(row["phone"])
        if not email_valid and not phone_valid:
            continue

        updated_dt = parse_updated(row["updated"])
        prepared.append({
            "index": index,
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "email": email if email_valid else "",
            "phone": phone if phone_valid else "",
            "zip": normalize_zip(row["zip"]),
            "source": row["source"].strip().lower(),
            "updated_dt": updated_dt,
            "opted_out": row["opted_out"].strip().lower() in {"y", "yes", "true", "1"},
            "tags": row["tags"],
        })

    parent = list(range(len(prepared)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        root_a, root_b = find(a), find(b)
        if root_a != root_b:
            parent[root_b] = root_a

    email_owner = {}
    phone_name_owner = {}
    for i, person in enumerate(prepared):
        if person["email"]:
            if person["email"] in email_owner:
                union(i, email_owner[person["email"]])
            else:
                email_owner[person["email"]] = i

        if person["phone"] and person["last_name"]:
            key = (person["phone"], person["last_name"].casefold())
            if key in phone_name_owner:
                union(i, phone_name_owner[key])
            else:
                phone_name_owner[key] = i

    groups = {}
    for i, person in enumerate(prepared):
        groups.setdefault(find(i), []).append(person)

    def preferred(candidates):
        return min(
            candidates,
            key=lambda p: (
                p["source"] != "manual",
                -p["updated_dt"].timestamp(),
                p["index"],
            ),
        )

    output = []
    for group in sorted(groups.values(), key=lambda g: min(p["index"] for p in g)):
        result = {}

        for field in ("first_name", "last_name", "zip", "email", "phone", "source"):
            candidates = [p for p in group if p[field]]
            result[field] = preferred(candidates)[field] if candidates else ""

        tags = set()
        for person in group:
            tags.update(
                tag.strip().lower()
                for tag in re.split(r"[;,]", person["tags"])
                if tag.strip()
            )
        result["tags"] = ";".join(sorted(tags))
        result["opted_out"] = "Y" if any(p["opted_out"] for p in group) else "N"
        result["updated"] = max(p["updated_dt"] for p in group).strftime("%Y-%m-%d")
        output.append(result)

    return output
